INSERT INTO dwh.dim_seller(seller_id,seller_name,region)
 SELECT seller_id,seller_name,region FROM staging.sellers;
INSERT INTO dwh.dim_product(product_id,product_name,category,price)
 SELECT product_id,product_name,category,price FROM staging.products;
INSERT INTO dwh.dim_customer(customer_id,customer_name)
 SELECT customer_id,customer_name FROM staging.customers;
INSERT INTO dwh.dim_date(date_key,full_date,year,month,day)
 SELECT DISTINCT TO_CHAR(dt,'YYYYMMDD')::integer,dt,
 EXTRACT(YEAR FROM dt)::integer,EXTRACT(MONTH FROM dt)::integer,EXTRACT(DAY FROM dt)::integer
 FROM staging.orders;
INSERT INTO dwh.fact_orders(order_id,dt,seller_key,product_key,customer_key,date_key,quantity,amount,commission)
 SELECT o.order_id,o.dt,s.seller_key,p.product_key,c.customer_key,d.date_key,o.quantity,o.amount,
 ROUND(o.amount*0.12,2)
 FROM staging.orders o
 JOIN dwh.dim_seller s ON s.seller_id=o.seller_id
 JOIN dwh.dim_product p ON p.product_id=o.product_id
 LEFT JOIN dwh.dim_customer c ON c.customer_id=o.customer_id
 JOIN dwh.dim_date d ON d.full_date=o.dt
 WHERE o.status='completed';
INSERT INTO analytics.daily_summary(dt,total_orders,revenue,average_basket,commission)
 SELECT dt,COUNT(*),SUM(amount),ROUND(AVG(amount),2),SUM(commission)
 FROM dwh.fact_orders GROUP BY dt;
INSERT INTO analytics.sales_anomalies(dt,revenue,average_previous_7_days,ratio,is_anomaly)
 SELECT a.dt,a.revenue, p.avg_rev,
 ROUND(a.revenue/NULLIF(p.avg_rev,0),4),
 CASE WHEN p.n=7 THEN a.revenue < 0.7*p.avg_rev ELSE NULL END
 FROM analytics.daily_summary a CROSS JOIN LATERAL
 (SELECT AVG(revenue) avg_rev,COUNT(*) n FROM analytics.daily_summary b
  WHERE b.dt >= a.dt - INTERVAL '7 days' AND b.dt < a.dt) p;
COMMIT;
SELECT (SELECT COUNT(*) FROM staging.orders) AS commandes_brutes,
 (SELECT COUNT(*) FROM dwh.fact_orders) AS commandes_validees,
 (SELECT COUNT(*) FROM staging.orders WHERE status='cancelled') AS annulations;
